// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.util.Set;
import java.util.TreeSet;
import java.util.function.Consumer;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Two queries that differ only in an operator parameter (property-path {@code minLength}, {@code GROUP_CONCAT}
 * separator) share a routing fingerprint. The packed plan cache must never authenticate one as the other: every test
 * compares with hand-computed results and with a cold store loaded with the same data (oracle), in both orders.
 */
class LmdbPackedPlanCacheOperatorParameterTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:p");
	private static final IRI A = VF.createIRI("urn:a");
	private static final IRI B = VF.createIRI("urn:b");

	private static final String STAR = "SELECT ?s ?o WHERE { ?s <urn:p>* ?o }";
	private static final String PLUS = "SELECT ?s ?o WHERE { ?s <urn:p>+ ?o }";
	private static final String COMMA = "SELECT (GROUP_CONCAT(STR(?o); separator=\",\") AS ?c) WHERE { ?s <urn:p> ?o }";
	private static final String PIPE = "SELECT (GROUP_CONCAT(STR(?o); separator=\"|\") AS ?c) WHERE { ?s <urn:p> ?o }";

	private static final Set<String> STAR_ROWS = Set.of("urn:a|urn:a", "urn:a|urn:b", "urn:b|urn:b");
	private static final Set<String> PLUS_ROWS = Set.of("urn:a|urn:b");

	@Test
	void packedPlanCacheMustNotServeStarPathPlanForPlusPath(@TempDir File dataDir, @TempDir File oracleDir) {
		Set<String> oracle = oracle(oracleDir, connection -> connection.add(A, P, B), PLUS, "s", "o");
		assertEquals(PLUS_ROWS, oracle, "cold oracle");

		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, B);
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();

			assertEquals(STAR_ROWS, rows(connection, STAR, "s", "o"), "p* rows");
			explain(connection, STAR);
			Set<String> plusRows = rows(connection, PLUS, "s", "o");
			explain(connection, PLUS);

			assertEquals(oracle, plusRows, "p+ must not return zero-length rows from a cached p* plan");
			assertEquals(STAR_ROWS, rows(connection, STAR, "s", "o"), "p* rows after p+");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void packedPlanCacheMustNotServePlusPathPlanForStarPath(@TempDir File dataDir, @TempDir File oracleDir) {
		Set<String> oracle = oracle(oracleDir, connection -> connection.add(A, P, B), STAR, "s", "o");
		assertEquals(STAR_ROWS, oracle, "cold oracle");

		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, B);
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();

			assertEquals(PLUS_ROWS, rows(connection, PLUS, "s", "o"), "p+ rows");
			explain(connection, PLUS);
			Set<String> starRows = rows(connection, STAR, "s", "o");
			explain(connection, STAR);

			assertEquals(oracle, starRows, "p* must not lose zero-length rows to a cached p+ plan");
			assertEquals(PLUS_ROWS, rows(connection, PLUS, "s", "o"), "p+ rows after p*");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void packedPlanCacheMustNotServeGroupConcatPlanWithOtherSeparator(@TempDir File dataDir) {
		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, VF.createLiteral("x"));
			connection.add(B, P, VF.createLiteral("y"));
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();

			assertSeparator(rows(connection, COMMA, "c"), ",", "|");
			explain(connection, COMMA);
			assertSeparator(rows(connection, PIPE, "c"), "|", ",");
			explain(connection, PIPE);
			assertSeparator(rows(connection, COMMA, "c"), ",", "|");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void packedPlanCacheMustNotServeGroupConcatPlanWithOtherSeparatorReversed(@TempDir File dataDir) {
		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, VF.createLiteral("x"));
			connection.add(B, P, VF.createLiteral("y"));
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();

			assertSeparator(rows(connection, PIPE, "c"), "|", ",");
			assertSeparator(rows(connection, COMMA, "c"), ",", "|");
			assertSeparator(rows(connection, PIPE, "c"), "|", ",");
		} finally {
			repository.shutDown();
		}
	}

	private static void assertSeparator(Set<String> rows, String expected, String forbidden) {
		assertEquals(1, rows.size(), "GROUP_CONCAT over one group yields one row");
		String value = rows.iterator().next();
		assertTrue(value.contains(expected) && !value.contains(forbidden),
				"GROUP_CONCAT with separator '" + expected + "' returned '" + value + "'");
	}

	private static SailRepository repository(File dataDir) {
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		repository.init();
		return repository;
	}

	private static Set<String> oracle(File dataDir, Consumer<RepositoryConnection> loader, String query,
			String... names) {
		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			loader.accept(connection);
			connection.commit();
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();
			return rows(connection, query, names);
		} finally {
			repository.shutDown();
		}
	}

	private static Set<String> rows(RepositoryConnection connection, String query, String... names) {
		Set<String> rows = new TreeSet<>();
		try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			for (BindingSet bindingSet : result) {
				StringBuilder row = new StringBuilder();
				for (int index = 0; index < names.length; index++) {
					if (index > 0) {
						row.append('|');
					}
					row.append(bindingSet.getValue(names[index]) == null ? "UNBOUND"
							: bindingSet.getValue(names[index]).stringValue());
				}
				rows.add(row.toString());
			}
		}
		return rows;
	}

	private static TupleExpr explain(RepositoryConnection connection, String query) {
		return (TupleExpr) connection.prepareTupleQuery(query).explain(Explanation.Level.Optimized).tupleExpr();
	}
}
